import { useState } from "react";
import { useNavigate } from "react-router-dom";
import AuthLayout from "../../components/AuthLayout";
import { canSubmitAccountForm } from "../../utils/accountValidation";

const GoogleIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24">
    <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
    <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
    <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z"/>
    <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
  </svg>
);

// ✅ مكون أيقونة Apple الرسمي
const AppleIcon = () => (
  <svg width="18" height="18" viewBox="0 0 384 512" fill="currentColor">
    <path d="M318.7 268.7c-.2-36.7 16.4-64.4 50-84.8-18.8-26.9-47.2-41.7-84.7-44.6-35.5-2.8-74.3 20.7-88.5 20.7-15 0-49.4-19.7-76.4-19.7C63.3 141.2 4 184.8 4 273.5q0 39.3 14.4 81.2c12.8 36.7 59 126.7 107.2 125.2 25.2-.6 43-17.9 75.8-17.9 31.8 0 48.3 17.9 76.4 17.9 48.6-.7 90.4-82.5 102.6-119.3-65.2-30.7-61.7-90-61.7-91.9zm-56.6-164.2c27.3-32.4 24.8-61.9 24-72.5-24.1 1.4-52 16.4-67.9 34.9-17.5 19.8-27.8 44.3-25.6 71.9 26.1 2 49.9-11.4 69.5-34.3z"/>
  </svg>
);

const leftContent = (
  <div>
    <p className="text-[11px] tracking-widest text-white/50 uppercase mb-2">BUSINESS</p>
    <p className="text-xs text-white/50 mb-5">STEP 1 OF 3 — ACCOUNT</p>
    <h2 className="font-serif text-4xl font-normal text-white leading-snug mb-8">
      Find the talent<br /><em>Algeria has to offer.</em>
    </h2>
    <ul className="flex flex-col gap-3">
      {/* ✅ تحديث الولايات إلى 69 */}
      {["Post jobs across all 69 wilayas", "Browse verified professionals", "Commission freelancers directly", "Build a verified company presence"].map((item) => (
        <li key={item} className="flex items-center gap-3 text-sm text-white/80">
          <span className="w-5 h-5 rounded-full bg-white/20 flex items-center justify-center text-xs text-white flex-shrink-0">✓</span>
          {item}
        </li>
      ))}
    </ul>
  </div>
);

export default function RegisterPage() {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [agreedToTerms, setAgreedToTerms] = useState(false);

  const canContinue = canSubmitAccountForm({
    email,
    password,
    confirmPassword,
    agreedToTerms,
  });

  const handleContinue = () => {
    if (!canContinue) return;
    navigate("/verify-email", { state: { email: email.trim() } });
  };

  return (
    <AuthLayout leftContent={leftContent} leftBg="bg-red">
      <h2 className="font-serif text-3xl font-normal mb-1">Create your account</h2>
      <p className="text-sm text-gray-500 mb-7">Business credentials for WorkBridge DZ.</p>

      <label className="block text-sm font-medium mb-1">Business Email</label>
      <input
        type="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        className="w-full px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm mb-4 outline-none focus:border-navy focus:bg-white"
        placeholder="you@company.dz"
      />

      <label className="block text-sm font-medium mb-1">Password</label>
      <input
        type="password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="w-full px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm mb-1 outline-none focus:border-navy focus:bg-white"
        placeholder="Enter a password"
      />
      <p className="text-xs text-gray-400 mb-4">At least 8 characters</p>

      <label className="block text-sm font-medium mb-1">Confirm Password</label>
      <input
        type="password"
        value={confirmPassword}
        onChange={(e) => setConfirmPassword(e.target.value)}
        className="w-full px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm mb-5 outline-none focus:border-navy focus:bg-white"
        placeholder="Repeat your password"
      />

      <div className="relative flex items-center justify-center mb-4">
        <div className="absolute w-full h-px bg-gray-200" />
        <span className="relative bg-cream px-3 text-xs text-gray-400">Or continue with</span>
      </div>

      <div className="flex gap-3 mb-4">
        <button className="flex-1 flex items-center justify-center gap-2 py-2.5 border border-gray-200 rounded-xl text-sm bg-white hover:bg-cream transition-all"><GoogleIcon /> Google</button>
        {/* ✅ استخدام أيقونة Apple الجديدة */}
        <button className="flex-1 flex items-center justify-center gap-2 py-2.5 border border-gray-200 rounded-xl text-sm bg-white hover:bg-cream transition-all"><AppleIcon /> Apple</button>
      </div>

      <label className="flex items-center gap-2 text-sm text-gray-500 mb-5 cursor-pointer">
        <input
          type="checkbox"
          checked={agreedToTerms}
          onChange={(e) => setAgreedToTerms(e.target.checked)}
          className="w-4 h-4 accent-navy"
        />
        <span>
          I agree to the <span className="text-navy underline">Terms of Service</span> and{" "}
          <span className="text-navy underline">Privacy Policy</span>
        </span>
      </label>

      <button
        type="button"
        disabled={!canContinue}
        onClick={handleContinue}
        className={`w-full py-3.5 rounded-full text-sm font-medium transition-all
          ${canContinue
            ? "bg-red text-white hover:bg-red-dark"
            : "bg-red/40 text-white/80 cursor-not-allowed"}`}
      >
        Continue →
      </button>

      <p className="text-sm text-gray-500 text-center mt-4">
        Already have an account?{" "}
        <span className="text-navy underline cursor-pointer" onClick={() => navigate("/sign-in")}>Sign in</span>
      </p>
    </AuthLayout>
  );
}
